export function Backdrop({
  color = "{{color}}",
  opacity = {{opacity}},
  blur = {{blur}},
  style = "{{style}}",
  visible = {{visible}},
}) {
  const layerBackground = {
    solid: color,
    blurred: color,
    gradient: "linear-gradient(to top, " + color + ", transparent)",
  }[style] ?? color;
  return (
    <div style={{ position: "relative", minHeight: 380, borderRadius: 12, overflow: "hidden",
      background: "#FAF7F2", display: "grid", placeItems: "center" }}>
      <div aria-hidden="true" style={{ position: "absolute", inset: 0, display: "grid",
        gridTemplateColumns: "repeat(3, 1fr)", gap: 10, padding: 20, boxSizing: "border-box" }}>
        <div style={{ background: "linear-gradient(135deg, #BFD9F2, #D9C8F0)", borderRadius: 10 }} />
        <div style={{ background: "linear-gradient(135deg, #BFD9F2, #D9C8F0)", borderRadius: 10 }} />
        <div style={{ background: "linear-gradient(135deg, #BFD9F2, #D9C8F0)", borderRadius: 10 }} />
      </div>
      {visible && (
        <div style={{ position: "absolute", inset: 0, background: layerBackground, opacity: opacity / 100,
          backdropFilter: style === "blurred" ? "blur(" + blur + "px)" : "none",
          WebkitBackdropFilter: style === "blurred" ? "blur(" + blur + "px)" : "none" }} />
      )}
      <div style={{ position: "relative", zIndex: 1, background: "#FAF7F2", color: "#241430", borderRadius: 14,
        boxShadow: "0 20px 44px rgba(36,20,48,.28)", padding: 22, maxWidth: 280, textAlign: "center",
        fontFamily: "system-ui, sans-serif" }}>
        <h3 style={{ margin: "0 0 8px", fontSize: 16, fontWeight: 600 }}>Preview panel</h3>
        <p style={{ margin: 0, fontSize: 13, color: "#241430cc" }}>This card sits above the backdrop layer, which dims — and can blur — the content behind it.</p>
      </div>
    </div>
  );
}
